const PAGE = window.PAGE_I18N || {};

const store = {
  get(k) { try { return localStorage.getItem(k); } catch { return null; } },
  set(k, v) { try { localStorage.setItem(k, v); } catch { /* storage unavailable */ } },
};

function lookup(lang, key) {
  const p = PAGE[lang], c = COMMON[lang];
  if (p && p[key] != null) return p[key];
  if (c && c[key] != null) return c[key];
  return null;
}

let lang = store.get('lang') || ((navigator.language || '').toLowerCase().startsWith('en') ? 'en' : 'es');
if (!['es', 'en'].includes(lang)) lang = 'es';

// Current-language string; falls back to Spanish.
function t(key) { return lookup(lang, key) ?? lookup('es', key) ?? ''; }
// Current-language field of a { es, en } object.
const L = o => (o && (o[lang] ?? o.es)) || '';

// Text built by this script that must follow the language switch: [element, source, property]
const bound = [];
function paint(el, src, prop) {
  const v = typeof src === 'function' ? src() : L(src);
  if (prop === 'textContent') el.textContent = v; else el.setAttribute(prop, v);
}
function bind(el, src, prop = 'textContent') {
  bound.push([el, src, prop]);
  paint(el, src, prop);
  return el;
}
document.addEventListener('langchange', () => bound.forEach(b => paint(...b)));

const el = (tag, cls, html) => {
  const e = document.createElement(tag);
  if (cls) e.className = cls;
  if (html != null) e.innerHTML = html;
  return e;
};

// ═══ CONTACT: floating button + modal (injected on every page) ═══
function buildContact() {
  const fab = el('button', 'fab');
  fab.type = 'button';
  fab.dataset.contactOpen = '';
  fab.innerHTML = `<span class="pulse" aria-hidden="true"></span>${ICON.mail}<span data-i18n="fab">${COMMON.es.fab}</span>`;

  const dlg = el('dialog', 'modal');
  dlg.id = 'contactModal';
  dlg.setAttribute('aria-labelledby', 'contactTitle');
  const s = COMMON.es;
  dlg.innerHTML = `
    <div class="modal-hd">
      <span class="avail"><span class="pulse" aria-hidden="true"></span><span data-i18n="cm.avail">${s['cm.avail']}</span></span>
      <h2 id="contactTitle" data-i18n="cm.title">${s['cm.title']}</h2>
      <p data-i18n="cm.sub">${s['cm.sub']}</p>
      <button type="button" class="modal-x" data-contact-close aria-label="${s['cm.close']}" data-i18n-attr="aria-label:cm.close">${ICON.x}</button>
    </div>
    <form class="modal-bd" id="contactForm">
      <div class="form-row">
        <div class="field"><label for="cf-name" data-i18n="cm.name">${s['cm.name']}</label><input id="cf-name" name="name" required maxlength="120" autocomplete="name"></div>
        <div class="field"><label for="cf-email" data-i18n="cm.email">${s['cm.email']}</label><input id="cf-email" name="email" type="email" required maxlength="160" autocomplete="email"></div>
      </div>
      <div class="form-row">
        <div class="field"><label for="cf-reason" data-i18n="cm.reason">${s['cm.reason']}</label>
          <select id="cf-reason" name="reason">
            <option value="job" data-i18n="cm.r.job">${s['cm.r.job']}</option>
            <option value="intern" data-i18n="cm.r.intern">${s['cm.r.intern']}</option>
            <option value="project" data-i18n="cm.r.project">${s['cm.r.project']}</option>
            <option value="other" data-i18n="cm.r.other">${s['cm.r.other']}</option>
          </select>
        </div>
        <div class="field"><label for="cf-org" data-i18n="cm.org">${s['cm.org']}</label><input id="cf-org" name="company" maxlength="160" autocomplete="organization"></div>
      </div>
      <div class="field"><label for="cf-msg" data-i18n="cm.msg">${s['cm.msg']}</label><textarea id="cf-msg" name="message" required maxlength="4000" placeholder="${s['cm.msg.ph']}" data-i18n-attr="placeholder:cm.msg.ph"></textarea></div>
      <input type="text" name="_honey" class="hp" tabindex="-1" autocomplete="off" aria-hidden="true">
      <div class="form-foot">
        <span class="form-alt"><span data-i18n="cm.alt">${s['cm.alt']}</span> <a href="mailto:${CONTACT_EMAIL}">${CONTACT_EMAIL}</a></span>
        <button type="submit" class="btn btn-primary btn-send">${ICON.mail}<span class="send-lbl" data-i18n="cm.send">${s['cm.send']}</span></button>
      </div>
      <div class="form-status" role="status" aria-live="polite"></div>
    </form>`;

  document.body.append(fab, dlg);
}

function initContact() {
  const dlg = document.getElementById('contactModal');
  const form = document.getElementById('contactForm');
  const statusEl = form.querySelector('.form-status');
  const sendBtn = form.querySelector('.btn-send');
  const sendLbl = sendBtn.querySelector('.send-lbl');
  const html = document.documentElement;

  const open = (reason) => {
    if (typeof dlg.showModal !== 'function') { location.href = 'mailto:' + CONTACT_EMAIL; return; }
    if (reason) form.elements.reason.value = reason;
    statusEl.className = 'form-status';
    dlg.showModal();
    html.classList.add('modal-open');
    form.querySelector('#cf-name').focus();
  };

  document.addEventListener('click', e => {
    const trigger = e.target.closest('[data-contact-open]');
    if (trigger) { e.preventDefault(); open(trigger.dataset.contactReason); }
  });
  dlg.addEventListener('click', e => {
    if (e.target === dlg || e.target.closest('[data-contact-close]')) dlg.close();
  });
  dlg.addEventListener('close', () => html.classList.remove('modal-open'));

  const mailto = (subject, body) =>
    `mailto:${CONTACT_EMAIL}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;

  form.addEventListener('submit', async e => {
    e.preventDefault();
    if (!form.reportValidity()) return;
    const fd = new FormData(form);
    if (fd.get('_honey')) return;

    const sel = form.elements.reason;
    const reason = sel.options[sel.selectedIndex].text;
    const name = String(fd.get('name')).trim();
    const email = String(fd.get('email')).trim();
    const company = String(fd.get('company') || '').trim();
    const message = String(fd.get('message')).trim();
    const subject = `Portafolio · ${reason} · ${name}`;

    sendBtn.disabled = true;
    sendLbl.textContent = t('cm.sending');
    statusEl.className = 'form-status';
    try {
      const res = await fetch(FORM_ENDPOINT, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
        body: JSON.stringify({
          nombre: name, email, motivo: reason, empresa: company || '—', mensaje: message,
          pagina: location.href, _subject: subject, _template: 'table', _captcha: 'false',
        }),
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok || String(data.success) !== 'true') throw new Error(data.message || res.status);
      form.reset();
      statusEl.textContent = t('cm.ok');
      statusEl.className = 'form-status ok';
    } catch {
      const body = `${message}\n\n— ${name} (${email})${company ? ' · ' + company : ''}`;
      statusEl.innerHTML = `${t('cm.err')} <a href="${mailto(subject, body)}">${t('cm.err.link')}</a>`;
      statusEl.className = 'form-status err';
    } finally {
      sendBtn.disabled = false;
      sendLbl.textContent = t('cm.send');
    }
  });
}

// ═══ LIGHTBOX ═══
// Items: { thumb, full, cap(), sub() }. The thumbnail (already loaded in the grid) shows at once,
// slightly blurred, and is swapped for the large version when it arrives; neighbours are preloaded.
let lb = null;
function buildLightbox() {
  const s = COMMON.es;
  const d = el('dialog', 'lightbox');
  d.setAttribute('aria-label', s['lb.label']);
  d.dataset.i18nAttr = 'aria-label:lb.label';
  d.innerHTML = `
    <div class="lb-inner">
      <span class="lb-count" aria-live="polite"></span>
      <img class="lb-img" alt="">
      <p class="lb-cap"></p>
      <p class="lb-set"></p>
      <button type="button" class="lb-btn lb-close" aria-label="${s['lb.close']}" data-i18n-attr="aria-label:lb.close">${ICON.x}</button>
      <button type="button" class="lb-btn lb-prev" aria-label="${s['lb.prev']}" data-i18n-attr="aria-label:lb.prev">${ICON.prev}</button>
      <button type="button" class="lb-btn lb-next" aria-label="${s['lb.next']}" data-i18n-attr="aria-label:lb.next">${ICON.next}</button>
    </div>`;
  document.body.appendChild(d);

  const img = d.querySelector('.lb-img'), cap = d.querySelector('.lb-cap');
  const sub = d.querySelector('.lb-set'), count = d.querySelector('.lb-count');
  let items = [], i = 0, onClose = null, token = 0;

  const preload = n => {
    const it = items[(n + items.length) % items.length];
    if (it && it.full) { const im = new Image(); im.decoding = 'async'; im.src = it.full; }
  };
  const text = () => {
    const it = items[i];
    img.alt = cap.textContent = it.cap();
    sub.textContent = it.sub ? it.sub() : '';
  };
  const show = n => {
    i = (n + items.length) % items.length;
    const it = items[i], my = ++token;
    const hi = new Image();
    hi.decoding = 'async';
    hi.src = it.full;
    if ((hi.complete && hi.naturalWidth) || !it.thumb) {
      img.classList.remove('lo');
      img.src = it.full;
    } else {
      img.classList.add('lo');
      img.src = it.thumb;
      hi.onload = () => { if (my === token) { img.src = it.full; img.classList.remove('lo'); } };
    }
    text();
    count.textContent = `${i + 1} / ${items.length}`;
    if (items.length > 1) { preload(i + 1); preload(i - 1); }
  };
  d.querySelector('.lb-prev').addEventListener('click', () => show(i - 1));
  d.querySelector('.lb-next').addEventListener('click', () => show(i + 1));
  d.querySelector('.lb-close').addEventListener('click', () => d.close());
  d.addEventListener('click', e => { if (e.target === d || e.target.classList.contains('lb-inner')) d.close(); });
  d.addEventListener('keydown', e => {
    if (items.length < 2) return;
    if (e.key === 'ArrowLeft') show(i - 1);
    if (e.key === 'ArrowRight') show(i + 1);
  });
  let x0 = null;   // swipe on touch screens
  d.addEventListener('touchstart', e => { x0 = e.touches[0].clientX; }, { passive: true });
  d.addEventListener('touchend', e => {
    if (x0 === null || items.length < 2) return;
    const dx = e.changedTouches[0].clientX - x0;
    x0 = null;
    if (Math.abs(dx) > 50) show(i + (dx < 0 ? 1 : -1));
  });
  d.addEventListener('close', () => {
    document.documentElement.classList.remove('modal-open');
    if (onClose) onClose(i);
  });
  document.addEventListener('langchange', () => { if (d.open) text(); });

  lb = {
    open(list, start, cb) {
      if (!list.length) return;
      if (typeof d.showModal !== 'function') { window.open(list[start].full, '_blank'); return; }
      items = list; onClose = cb || null;
      d.classList.toggle('single', list.length < 2);
      show(start);
      d.showModal();
      document.documentElement.classList.add('modal-open');
    },
  };
}

// Lightbox item for a plain <img> (stand-alone figures)
const imgItem = im => ({
  thumb: im.currentSrc || im.src,
  full: im.dataset.full || im.currentSrc || im.src,
  cap: () => { const fc = im.closest('figure')?.querySelector('figcaption'); return fc ? fc.textContent.trim() : im.alt; },
});

// Stand-alone zoomable images: <img data-zoom> (grouped by the closest [data-gallery])
function initZoom() {
  document.querySelectorAll('img[data-zoom]').forEach(im => {
    im.addEventListener('click', () => {
      const group = im.closest('[data-gallery]');
      const list = group ? [...group.querySelectorAll('img[data-zoom]')] : [im];
      lb.open(list.map(imgItem), list.indexOf(im));
    });
  });
}

// ═══ EVIDENCE PHOTOS (manifest → <img>, tiles, lightbox items) ═══
const G = window.GALLERY || null;
const [SMALL, LARGE] = G ? G.sizes : [720, 1600];
const photoURL = (id, size) => new URL(`${G.base}${id}-${size}.webp`, ROOT).href;
const siteURL = path => new URL(path, ROOT).href;
const setOf = id => G.sets[id.split('/')[0]];
const colOf = id => G.collections.find(c => c.id === setOf(id).col);
const colCount = c => c.sets.reduce((n, s) => n + G.sets[s].photos.length, 0);

function photo(id) {
  const p = G && G.photos[id];
  return p ? Object.assign({ id }, p) : null;
}

// "set/slug" picks one photo, "set/*" every photo of a set
function pick(spec) {
  if (!G || !spec) return [];
  return spec.split(/[\s,]+/).filter(Boolean).flatMap(tok => {
    const [sid, slug] = tok.split('/');
    return slug === '*' ? (G.sets[sid]?.photos || []).map(s => `${sid}/${s}`) : [tok];
  }).map(photo).filter(Boolean);
}

function photoItem(p) {
  return {
    thumb: photoURL(p.id, SMALL),
    full: photoURL(p.id, LARGE),
    cap: () => L(p),
    sub: () => {
      const s = setOf(p.id), c = colOf(p.id);
      return L(s) === L(c) ? L(c) : `${L(s)} · ${L(c)}`;
    },
  };
}

// Responsive, lazy <img>: the browser picks the 720 or 1600 px file from `sizes`
function photoImg(p, sizes, eager) {
  const im = new Image();
  im.decoding = 'async';
  if (!eager) im.loading = 'lazy';
  im.width = p.tw;
  im.height = p.th;
  im.sizes = sizes;
  im.srcset = `${photoURL(p.id, SMALL)} ${p.tw}w, ${photoURL(p.id, LARGE)} ${p.w}w`;
  im.src = photoURL(p.id, SMALL);
  im.dataset.full = photoURL(p.id, LARGE);
  const done = () => im.classList.add('ld');
  if (im.complete && im.naturalWidth) done();
  else { im.addEventListener('load', done, { once: true }); im.addEventListener('error', done, { once: true }); }
  bind(im, p, 'alt');
  return im;
}

// Square thumbnail button; clicking opens the lightbox over `list` (array of photos)
function tile(p, list, sizes) {
  const fig = el('figure', 'ph');
  fig.style.backgroundColor = p.c;
  const btn = el('button', 'ph-btn');
  btn.type = 'button';
  btn.appendChild(photoImg(p, sizes));
  btn.addEventListener('click', () => lb.open(list().map(photoItem), list().indexOf(p)));
  const cap = el('figcaption');
  cap.setAttribute('aria-hidden', 'true');
  bind(cap, p);
  fig.append(btn, cap);
  return fig;
}

// <div data-mosaic>: featured photos on the home page
function initMosaic(root) {
  const list = G.featured.map(photo).filter(Boolean);
  list.forEach((p, n) => root.appendChild(tile(p, () => list,
    n === 0 ? '(max-width: 600px) 100vw, 560px' : '(max-width: 600px) 50vw, (max-width: 900px) 33vw, 280px')));
}

// <div data-gal-links>: one chip per collection, linking into the gallery page
function initGalLinks(root) {
  G.collections.forEach(c => {
    const a = el('a', 'chip-f');
    a.href = siteURL(`galeria.html#${c.id}`);
    if (c.color) a.style.setProperty('--c', c.color);
    a.append(el('i', `ic ic-${c.icon}`), bind(el('span'), c), el('span', 'n', String(colCount(c))));
    root.appendChild(a);
  });
}

// <div data-thumbs="set/slug …">: small tiles (timeline cards)
function initThumbs(root) {
  const list = pick(root.dataset.thumbs);
  list.forEach(p => root.appendChild(tile(p, () => list, '80px')));
}

// [data-count] / [data-count="collection"]: photo totals, written into the first text node
function initCounts() {
  document.querySelectorAll('[data-count]').forEach(e => {
    const c = G.collections.find(x => x.id === e.dataset.count);
    const n = String(c ? colCount(c) : G.total);
    const node = [...e.childNodes].find(x => x.nodeType === 3 && /\d/.test(x.nodeValue));
    if (node) node.nodeValue = node.nodeValue.replace(/\d+/, n); else e.prepend(n);
  });
}

// <main data-gallery>: every collection, filterable by chips in [data-gal-filters]
function initGalleryPage(root) {
  const bar = document.querySelector('[data-gal-filters]');
  bind(bar, () => t('gal.filters'), 'aria-label');
  const order = [];      // photos of the visible collections, in page order (for the lightbox)
  const sections = G.collections.map(c => {
    const sec = el('article', 'gal-sec');
    sec.id = c.id;
    if (c.color) sec.style.setProperty('--c', c.color);
    const hd = el('header', 'gal-hd');
    const left = el('div');
    const h2 = el('h2');
    h2.append(el('i', `ic ic-${c.icon}`), bind(el('span'), c));
    const meta = el('p', 'gal-meta');
    bind(meta, () => [L(c.ctx), L(c.period), `${colCount(c)} ${t('gal.photos')}`].filter(Boolean).join(' · '));
    left.append(h2, meta);
    hd.appendChild(left);
    if (c.page) {
      const a = el('a', 'gal-link');
      a.href = siteURL(c.page);
      bind(a, () => `${t('gal.details')} →`);
      hd.appendChild(a);
    }
    sec.appendChild(hd);
    const photos = [];   // the same objects the tiles hold, so the lightbox can find them
    c.sets.forEach(sid => {
      const s = G.sets[sid];
      if (c.sets.length > 1) {
        const h3 = el('h3', 'gal-set');
        h3.append(bind(el('span'), s), el('span', 'n', String(s.photos.length)));
        sec.appendChild(h3);
      }
      const grid = el('div', 'gal-grid');
      s.photos.forEach(slug => {
        const p = photo(`${sid}/${slug}`);
        if (!p) return;
        photos.push(p);
        grid.appendChild(tile(p, () => order, '(max-width: 480px) 50vw, (max-width: 600px) 33vw, 240px'));
      });
      sec.appendChild(grid);
    });
    root.appendChild(sec);
    return { c, sec, photos };
  });

  const chips = [null, ...G.collections].map(c => {
    const b = el('button', 'chip-f');
    b.type = 'button';
    if (c && c.color) b.style.setProperty('--c', c.color);
    b.append(el('i', `ic ic-${c ? c.icon : 'grid'}`), bind(el('span'), c || (() => t('gal.all'))),
      el('span', 'n', String(c ? colCount(c) : G.total)));
    b.addEventListener('click', () => setFilter(c ? c.id : '', true));
    bar.appendChild(b);
    return [c ? c.id : '', b];
  });

  function setFilter(id, user) {
    if (!G.collections.some(c => c.id === id)) id = '';
    chips.forEach(([cid, b]) => b.setAttribute('aria-pressed', String(cid === id)));
    order.length = 0;
    sections.forEach(({ c, sec, photos }) => {
      sec.hidden = !!id && c.id !== id;
      if (!sec.hidden) order.push(...photos);
    });
    if (!user) return;
    history.replaceState(null, '', id ? `#${id}` : location.pathname + location.search);
    // back to the first result if the reader was further down, keeping the chosen chip in view
    const nav = document.getElementById('nav'), sticky = bar.closest('.gal-bar') || bar;
    const top = root.getBoundingClientRect().top + scrollY - (nav ? nav.offsetHeight : 0) - sticky.offsetHeight;
    if (scrollY > top) scrollTo({ top, behavior: REDUCED ? 'auto' : 'smooth' });
    const chip = chips.find(([cid]) => cid === id)[1];
    bar.scrollTo({ left: chip.offsetLeft - (bar.clientWidth - chip.offsetWidth) / 2, behavior: REDUCED ? 'auto' : 'smooth' });
  }
  setFilter(decodeURIComponent(location.hash.slice(1)));
  addEventListener('hashchange', () => setFilter(decodeURIComponent(location.hash.slice(1))));
}

// ═══ CAROUSEL ═══
// <div class="car" data-carousel data-photos="set/slug set/* …" data-more="collection"></div>
// is filled from the manifest; static markup (.carousel > .car-track > figure.car-slide*) also works.
function buildCarousel(root) {
  const list = pick(root.dataset.photos);
  if (!list.length) return null;
  root.innerHTML = `<div class="carousel"><div class="car-track" tabindex="0"></div>
    <button type="button" class="car-btn car-prev">${ICON.prev}</button>
    <button type="button" class="car-btn car-next">${ICON.next}</button>
    <span class="car-count" aria-hidden="true"></span></div><div class="car-dots"></div>`;
  const track = root.querySelector('.car-track');
  bind(track, () => t('car.label'), 'aria-label');
  bind(root.querySelector('.car-prev'), () => t('car.prev'), 'aria-label');
  bind(root.querySelector('.car-next'), () => t('car.next'), 'aria-label');
  list.forEach((p, n) => {
    const fig = el('figure', 'car-slide');
    const im = photoImg(p, '(max-width: 900px) 100vw, 760px', n === 0);
    // the blurred backdrop reuses the slide's own file once it has loaded: no extra download
    im.addEventListener('load', () => fig.style.setProperty('--img', `url("${im.currentSrc || im.src}")`), { once: true });
    fig.append(im, bind(el('figcaption'), p));
    track.appendChild(fig);
  });
  const c = G.collections.find(x => x.id === root.dataset.more);
  if (c) {
    const foot = el('div', 'car-foot');
    const a = el('a');
    a.href = siteURL(`galeria.html#${c.id}`);
    bind(a, () => `${t('gal.more').replace('{n}', colCount(c))} →`);
    foot.appendChild(a);
    root.appendChild(foot);
  }
  return list.map(photoItem);
}

function initCarousel(root) {
  const built = root.dataset.photos ? buildCarousel(root) : null;
  const track = root.querySelector('.car-track');
  if (!track) return;
  const slides = [...track.children];
  const imgs = slides.map(s => s.querySelector('img'));
  const items = built || imgs.map(imgItem);
  const dots = root.querySelector('.car-dots');
  const count = root.querySelector('.car-count');
  let idx = 0;

  slides.forEach((s, n) => {
    s.setAttribute('role', 'group');
    s.setAttribute('aria-roledescription', 'slide');
    s.setAttribute('aria-label', `${n + 1} / ${slides.length}`);
  });

  const dotBtns = slides.map((_, n) => {
    const b = el('button', 'car-dot');
    b.type = 'button';
    b.addEventListener('click', () => go(n));
    if (dots) dots.appendChild(b);
    return b;
  });

  const labelDots = () => dotBtns.forEach((b, n) => b.setAttribute('aria-label', `${t('car.goto')} ${n + 1}`));
  document.addEventListener('langchange', labelDots);
  labelDots();

  function update() {
    dotBtns.forEach((b, n) => b.setAttribute('aria-current', n === idx ? 'true' : 'false'));
    if (count) count.textContent = `${idx + 1} / ${slides.length}`;
  }
  function go(n, instant) {
    idx = (n + slides.length) % slides.length;
    track.scrollTo({ left: slides[idx].offsetLeft, behavior: instant ? 'auto' : 'smooth' });
    update();
  }

  const io = new IntersectionObserver(entries => {
    entries.forEach(e => {
      if (e.isIntersecting && e.intersectionRatio >= 0.6) { idx = slides.indexOf(e.target); update(); }
    });
  }, { root: track, threshold: [0.6] });
  slides.forEach(s => io.observe(s));

  root.querySelector('.car-prev')?.addEventListener('click', () => go(idx - 1));
  root.querySelector('.car-next')?.addEventListener('click', () => go(idx + 1));
  root.addEventListener('keydown', e => {
    if (e.target.closest('.car-dot')) return;
    if (e.key === 'ArrowLeft') { e.preventDefault(); go(idx - 1); }
    if (e.key === 'ArrowRight') { e.preventDefault(); go(idx + 1); }
  });
  imgs.forEach((im, n) => im && im.addEventListener('click', () => lb.open(items, n, last => go(last, true))));

  if (slides.length < 2) root.querySelectorAll('.car-btn').forEach(b => b.hidden = true);
  update();
}

function initGallery() {
  if (!G) return;
  document.querySelectorAll('[data-mosaic]').forEach(initMosaic);
  document.querySelectorAll('[data-gal-links]').forEach(initGalLinks);
  document.querySelectorAll('[data-thumbs]').forEach(initThumbs);
  document.querySelectorAll('[data-gallery]').forEach(initGalleryPage);
  initCounts();
}

// ═══ LANGUAGE ═══
const originals = new WeakMap();
const attrOriginals = new WeakMap();
const docTitle = document.title;
const metaDesc = document.querySelector('meta[name="description"]');
const metaDescOrig = metaDesc ? metaDesc.getAttribute('content') : '';

function applyLang(l) {
  lang = l;
  document.documentElement.lang = l;

  document.querySelectorAll('[data-i18n]').forEach(e => {
    if (!originals.has(e)) originals.set(e, e.innerHTML);
    const v = lookup(l, e.dataset.i18n);
    e.innerHTML = v != null ? v : originals.get(e);
  });

  document.querySelectorAll('[data-i18n-attr]').forEach(e => {
    const pairs = e.dataset.i18nAttr.split(';').map(p => p.split(':').map(x => x.trim()));
    let orig = attrOriginals.get(e);
    if (!orig) {
      orig = {};
      pairs.forEach(([a]) => { orig[a] = e.getAttribute(a); });
      attrOriginals.set(e, orig);
    }
    pairs.forEach(([a, k]) => {
      const v = lookup(l, k);
      e.setAttribute(a, v != null ? v : orig[a]);
    });
  });

  document.title = lookup(l, 'meta.title') ?? docTitle;
  if (metaDesc) metaDesc.setAttribute('content', lookup(l, 'meta.desc') ?? metaDescOrig);

  document.querySelectorAll('.lang-btn').forEach(b => {
    const on = b.dataset.lang === l;
    b.classList.toggle('active', on);
    b.setAttribute('aria-pressed', String(on));
  });

  store.set('lang', l);
  document.dispatchEvent(new CustomEvent('langchange', { detail: { lang: l } }));
}

// ═══ NAV ═══
function initNav() {
  const nav = document.getElementById('nav');
  if (!nav) return;
  const onScroll = () => nav.classList.toggle('scrolled', scrollY > 40);
  addEventListener('scroll', onScroll, { passive: true });
  onScroll();

  const toggle = document.getElementById('navToggle');
  const links = document.getElementById('navLinks');
  if (!toggle || !links) return;
  toggle.addEventListener('click', () => toggle.setAttribute('aria-expanded', String(links.classList.toggle('open'))));
  links.querySelectorAll('a').forEach(a => a.addEventListener('click', () => {
    links.classList.remove('open');
    toggle.setAttribute('aria-expanded', 'false');
  }));

  // Scroll-spy only for in-page anchors (home page)
  const spy = links.querySelectorAll('a[href^="#"]');
  if (!spy.length) return;
  document.querySelectorAll('section[id]').forEach(s => {
    new IntersectionObserver(entries => {
      entries.forEach(e => {
        if (e.isIntersecting) spy.forEach(a => a.classList.toggle('active', a.getAttribute('href') === '#' + e.target.id));
      });
    }, { threshold: 0.35 }).observe(s);
  });
}

// ═══ REVEAL ═══
// Elements that enter the viewport together fade in one after another.
function initReveal() {
  const els = document.querySelectorAll('.reveal');
  if (!('IntersectionObserver' in window)) { els.forEach(e => e.classList.add('visible')); return; }
  const ro = new IntersectionObserver(entries => {
    let k = 0;
    entries.forEach(e => {
      if (!e.isIntersecting) return;
      const t = e.target, delay = Math.min(k++, 6) * 80;
      if (delay) {
        t.style.transitionDelay = delay + 'ms';
        setTimeout(() => { t.style.transitionDelay = ''; }, delay + 700);
      }
      t.classList.add('visible');
      ro.unobserve(t);
    });
  }, { threshold: 0.1 });
  els.forEach(e => ro.observe(e));
}

const REDUCED = matchMedia('(prefers-reduced-motion: reduce)').matches;

// ═══ AMBIENT BACKGROUND (hero + detail headers) ═══
function initFx() {
  document.querySelectorAll('#inicio, .page-hero').forEach(host => {
    const fx = el('div', 'fx');
    fx.setAttribute('aria-hidden', 'true');
    fx.innerHTML = '<i class="fx-blob fx-b1"></i><i class="fx-blob fx-b2"></i><i class="fx-blob fx-b3"></i><i class="fx-blob fx-b4"></i><i class="fx-comb"></i>';
    host.querySelector('.page-cover') ? host.querySelector('.page-cover').after(fx) : host.prepend(fx);
    if (host.id === 'inicio') initBubbles(host, fx);
    fx.insertAdjacentHTML('beforeend', '<i class="fx-grain"></i>');
  });
}

// Effervescence behind the hero: honey- and foam-coloured bubbles rise and wobble like a
// fermenting mead or kombucha; the pointer pushes nearby bubbles aside.
// Paused off-screen and in background tabs.
function initBubbles(host, fx) {
  const cv = el('canvas', 'fx-net');
  fx.appendChild(cv);
  fx.insertAdjacentHTML('beforeend', '<i class="fx-veil"></i>');
  const ctx = cv.getContext('2d');
  if (!ctx) return;
  const TINTS = ['255,244,220', '255,244,220', '240,183,64', '240,183,64', '252,217,138', '170,206,120'];
  const REACH = 110;
  const mouse = { x: -1e4, y: -1e4 };
  let w = 0, h = 0, bs = [], raf = 0, inView = true;

  const spawn = bottom => {
    const r = Math.random() < 0.85 ? Math.random() * 3 + 1 : Math.random() * 7 + 4;
    return {
      x: Math.random() * w, y: bottom ? h + r + Math.random() * 40 : Math.random() * h, r,
      vy: -(0.25 + r * 0.06 + Math.random() * 0.35), ph: Math.random() * Math.PI * 2,
      amp: Math.random() * 0.45 + 0.15, c: TINTS[(Math.random() * TINTS.length) | 0], a: Math.random() * 0.35 + 0.25,
    };
  };
  // Existing bubbles are rescaled, not re-seeded, so height changes don't make the scene jump.
  function size() {
    const dpr = Math.min(window.devicePixelRatio || 1, 2), ow = w, oh = h;
    w = host.clientWidth; h = host.clientHeight;
    cv.width = w * dpr; cv.height = h * dpr;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    if (ow && oh) for (const b of bs) { b.x *= w / ow; b.y *= h / oh; }
    const n = Math.round(Math.min(110, Math.max(30, w * h / 11000)));
    while (bs.length < n) bs.push(spawn(false));
    bs.length = n;
  }
  function draw() {
    ctx.clearRect(0, 0, w, h);
    ctx.lineWidth = 1;
    for (const b of bs) {
      ctx.beginPath();
      ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
      ctx.fillStyle = `rgba(${b.c},${b.a * 0.22})`;
      ctx.fill();
      ctx.strokeStyle = `rgba(${b.c},${b.a})`;
      ctx.stroke();
      if (b.r > 2.5) {   // glint
        ctx.beginPath();
        ctx.arc(b.x - b.r * 0.35, b.y - b.r * 0.35, b.r * 0.28, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(255,255,255,${b.a * 0.9})`;
        ctx.fill();
      }
    }
  }
  function step() {
    for (const b of bs) {
      b.ph += 0.03;
      b.x += Math.sin(b.ph) * b.amp;
      b.y += b.vy;
      const dx = b.x - mouse.x, dy = b.y - mouse.y, d2 = dx * dx + dy * dy;
      if (d2 < REACH * REACH) {
        const d = Math.sqrt(d2) || 1, f = (1 - d / REACH) * 2.2;
        b.x += dx / d * f; b.y += dy / d * f;
      }
      if (b.y < -b.r - 10) Object.assign(b, spawn(true));
    }
    draw();
    raf = requestAnimationFrame(step);
  }
  function sync() {
    const run = inView && !document.hidden && !REDUCED;
    if (run && !raf) raf = requestAnimationFrame(step);
    if (!run && raf) { cancelAnimationFrame(raf); raf = 0; }
  }

  size(); draw();
  if ('ResizeObserver' in window) new ResizeObserver(() => { size(); draw(); }).observe(host);
  if ('IntersectionObserver' in window) new IntersectionObserver(([e]) => { inView = e.isIntersecting; sync(); }).observe(host);
  document.addEventListener('visibilitychange', sync);
  host.addEventListener('pointermove', e => {
    const r = host.getBoundingClientRect();
    mouse.x = e.clientX - r.left; mouse.y = e.clientY - r.top;
  }, { passive: true });
  host.addEventListener('pointerleave', () => { mouse.x = mouse.y = -1e4; });
  sync();
}

// ═══ CARDS: pointer-following light (mouse/trackpad only) ═══
function initSpotlight() {
  if (!matchMedia('(hover: hover) and (pointer: fine)').matches) return;
  document.querySelectorAll('.proj-card, .tl-card, .sk-group, .kpi, .mod, .rel-card, .contact-link, .edu')
    .forEach(e => e.classList.add('spot'));
  document.addEventListener('pointermove', e => {
    const s = e.target.closest && e.target.closest('.spot');
    if (!s) return;
    const r = s.getBoundingClientRect();
    s.style.setProperty('--mx', `${e.clientX - r.left}px`);
    s.style.setProperty('--my', `${e.clientY - r.top}px`);
  }, { passive: true });
}

// ═══ COUNTERS: figures count up when they scroll into view ═══
// Animates the first number in the element's leading text node ("172", "20+").
function initCounters() {
  if (REDUCED || !('IntersectionObserver' in window)) return;
  const io = new IntersectionObserver(entries => entries.forEach(e => {
    if (!e.isIntersecting) return;
    io.unobserve(e.target);
    const { node, pre, to, dec, post } = e.target._count;
    const t0 = performance.now(), dur = 1400;
    const tick = now => {
      const p = Math.min(1, (now - t0) / dur);
      node.nodeValue = pre + (to * (1 - Math.pow(1 - p, 3))).toFixed(dec) + post;
      if (p < 1) requestAnimationFrame(tick);
    };
    requestAnimationFrame(tick);
  }), { threshold: 0.6 });

  document.querySelectorAll('.nf-row .v, .m-val, .kpi .v').forEach(e => {
    const node = [...e.childNodes].find(n => n.nodeType === 3 && /\d/.test(n.nodeValue));
    const m = node && node.nodeValue.match(/^(\D*?)(\d+(?:\.\d+)?)([\s\S]*)$/);
    if (!m || m[1]) return;   // skip values such as "C1"
    const dec = (m[2].split('.')[1] || '').length;
    e._count = { node, pre: m[1], to: parseFloat(m[2]), dec, post: m[3] };
    node.nodeValue = m[1] + (0).toFixed(dec) + m[3];
    io.observe(e);
  });
}

// ═══ PAGE TRANSITIONS ═══
// Cards and detail headers share a view-transition-name so one morphs into the other.
// Names of elements that are off screen are dropped for the transition, so nothing
// flies in from outside the viewport.
function initPageTransitions() {
  if (!window.CSSViewTransitionRule) return;
  const named = [...document.querySelectorAll('[style*="view-transition-name:vt-"]')];
  named.forEach(e => { e.dataset.vt = e.style.viewTransitionName; });
  const dropOffscreen = () => named.forEach(e => {
    const r = e.getBoundingClientRect();
    if (r.bottom < 0 || r.top > innerHeight) e.style.viewTransitionName = 'none';
  });
  const restore = () => named.forEach(e => { e.style.viewTransitionName = e.dataset.vt; });
  addEventListener('pageswap', e => { if (e.viewTransition) dropOffscreen(); });
  addEventListener('pagereveal', e => {
    if (!e.viewTransition) return;
    dropOffscreen();
    e.viewTransition.finished.finally(restore);
  });
  addEventListener('pageshow', restore);
}

